// контрольных сумм изменённых файлов.
package watcher

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// FileInfo хранит информацию о файле: его путь, контрольную сумму и время
// последнего изменения.
type FileInfo struct {
	Path      string    // Полный путь к файлу
	Checksum  string    // Контрольная сумма SHA-256 в hex-формате
	ModTime   time.Time // Время последнего изменения файла
	Size      int64     // Размер файла в байтах
}

// Watcher следит за каталогом и отслеживает изменения файлов, пересчитывая
// их контрольные суммы при обнаружении изменений.
type Watcher struct {
	rootDir   string              // Корневой каталог для мониторинга
	files     map[string]*FileInfo // Карта путей файлов в их метаданные
	mu        sync.RWMutex        // Мьютекс для потокобезопасного доступа к files
	checksums map[string]string   // Кэш контрольных сумм по пути файла
	running   bool                // Флаг активности мониторинга
	stopChan  chan struct{}       // Канал для остановки мониторинга
	wg        sync.WaitGroup      // Группа ожидания для горутин
}

// NewWatcher создаёт новый экземпляр Watcher для указанного корневого каталога.
// Каталог должен существовать и быть доступным для чтения.
func NewWatcher(rootDir string) (*Watcher, error) {
	// Проверяем, что каталог существует и является директорией
	info, err := os.Stat(rootDir)
	if err != nil {
		return nil, fmt.Errorf("не удалось получить информацию о каталоге %s: %w", rootDir, err)
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("путь %s не является каталогом", rootDir)
	}

	w := &Watcher{
		rootDir:   rootDir,
		files:     make(map[string]*FileInfo),
		checksums: make(map[string]string),
		stopChan:  make(chan struct{}),
	}

	return w, nil
}

// Start запускает мониторинг каталога в отдельной горутине.
// Метод возвращает ошибку, если мониторинг уже запущен.
func (w *Watcher) Start() error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.running {
		return fmt.Errorf("мониторинг уже запущен")
	}

	w.running = true
	w.wg.Add(1)

	go w.monitorLoop()

	return nil
}

// Stop останавливает мониторинг каталога.
// Метод блокируется до завершения всех горутин мониторинга.
func (w *Watcher) Stop() {
	w.mu.Lock()
	if !w.running {
		w.mu.Unlock()
		return
	}
	w.running = false
	w

