public long updateRto(long sampleMs) {
    // Проверка на корректность входных данных: RTT (Round-Trip Time) не может быть отрицательным
    if (sampleMs < 0) {
        throw new IllegalArgumentException("negative RTT sample");
    }

    // Если это первое измерение RTT (srtt еще не инициализировано, значение < 0)
    if (srtt < 0) {
        // Инициализируем сглаженное значение RTT (SRTT) первым образцом
        srtt = sampleMs;
        // Инициализируем дисперсию RTT (RTTVAR) как половину первого образца
        // Это стандартная практика для начальной оценки вариативности
        rttvar = sampleMs / 2;
    } else {
        // Вычисляем абсолютную разницу между текущим сглаженным RTT и новым образцом
        long delta = Math.abs(srtt - sampleMs);

        // Обновляем дисперсию RTT (RTTVAR) с использованием экспоненциального сглаживания
        // Формула: RTTVAR = (3 * RTTVAR + |SRTT - RTT|) / 4
        // Это соответствует коэффициенту сглаживания 1/4 для дисперсии
        rttvar = (3 * rttvar + delta) / 4;

        // Обновляем сглаженное значение RTT (SRTT) с использованием экспоненциального сглаживания
        // Формула: SRTT = (7 * SRTT + RTT) / 8
        // Это соответствует коэффициенту сглаживания 1/8 для среднего значения
        srtt = (7 * srtt + sampleMs) / 8;
    }

    // Вычисляем таймаут повторной передачи (RTO) по формуле RFC 6298:
    // RTO = SRTT + max(G, 4 * RTTVAR)
    // где G — гранулярность таймера (минимальный шаг времени), чтобы избежать слишком малых значений
    long rto = srtt + Math.max(granularityMs, 4 * rttvar);

    // Ограничиваем значение RTO в допустимых пределах:
    // Минимальное значение — 1000 мс (1 секунда), максимальное — 60000 мс (60 секунд)
    // Это предотвращает слишком агрессивные повторные передачи или чрезмерные задержки
    return Math.min(Math.max(rto, 1000L), 60000L);
}
