public void Tick(double frameSeconds)
{
    // Ограничиваем время кадра максимальным значением, чтобы избежать
    // "спирали смерти" (spiral of death), когда физика не успевает обрабатывать
    // слишком большие временные интервалы (например, после зависания приложения)
    if (frameSeconds > MaxFrame)
        frameSeconds = MaxFrame;

    // Добавляем прошедшее время кадра к аккумулятору.
    // Аккумулятор накапливает время, которое ещё не было обработано физикой.
    _accumulator += frameSeconds;

    // Счётчик количества выполненных шагов физики за текущий кадр
    var steps = 0;

    // Пока в аккумуляторе накопилось достаточно времени для одного шага физики,
    // выполняем шаги с фиксированным временным шагом (Step)
    while (_accumulator >= Step)
    {
        // Обновляем мир (физическую симуляцию) на фиксированный шаг времени
        _world.Update(Step);

        // Вычитаем из аккумулятора время, которое было обработано этим шагом
        _accumulator -= Step;

        // Увеличиваем счётчик выполненных шагов
        if (++steps >= MaxStepsPerFrame)
        {
            // Если достигнут лимит шагов на кадр, сбрасываем аккумулятор,
            // чтобы избежать накопления огромного отставания, и выходим из цикла.
            // Это защита от чрезмерной нагрузки на процессор.
            _accumulator = 0;
            break;
        }
    }

    // Рендерим сцену, передавая интерполяционный коэффициент (alpha),
    // который показывает, какая доля следующего шага физики уже "прошла".
    // Это позволяет плавно интерполировать позиции объектов между
    // последним и следующим состояниями физики для плавной визуализации.
    _renderer.Draw(_world, _accumulator / Step);
}
