// WriteFileAtomic атомарно записывает данные в файл по указанному пути.
// Атомарность обеспечивается записью во временный файл с последующим переименованием,
// что гарантирует, что целевой файл либо содержит старые данные, либо новые, но никогда не будет поврежденным.
func WriteFileAtomic(path string, data []byte, perm os.FileMode) error {
	// Создаем временный файл в той же директории, что и целевой файл.
	// Это важно, так как переименование (rename) работает атомарно только в пределах одной файловой системы.
	tmp, err := os.CreateTemp(filepath.Dir(path), ".tmp-*")
	if err != nil {
		return err
	}

	// Гарантируем удаление временного файла при выходе из функции,
	// если что-то пошло не так. Если операция завершится успешно,
	// файл будет переименован, и os.Remove просто не найдет его (или проигнорирует ошибку).
	defer os.Remove(tmp.Name())

	// Записываем данные во временный файл.
	// Если запись прошла успешно, вызываем Sync(), чтобы убедиться,
	// что данные физически записаны на диск, а не остались в буфере ОС.
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Sync()
	}

	// Закрываем временный файл.
	// Если предыдущие операции прошли без ошибок, сохраняем ошибку от Close(), если она есть.
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}

	// Если все предыдущие шаги прошли успешно, устанавливаем нужные права доступа для временного файла.
	// Это необходимо, так как os.CreateTemp создает файлы с правами 0600,
	// а нам нужно задать права, указанные в параметре perm.
	if err == nil {
		err = os.Chmod(tmp.Name(), perm)
	}

	// Если на каком-то этапе возникла ошибка, возвращаем её.
	// Временный файл будет удален благодаря defer.
	if err != nil {
		return err
	}

	// Атомарно заменяем целевой файл временным.
	// Операция rename атомарна в пределах одной файловой системы,
	// поэтому другие процессы увидят либо старый файл, либо новый, но не промежуточное состояние.
	return os.Rename(tmp.Name(), path)
}
