#include <stdlib.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <string.h>

int main() {
    const char *filename = "example.txt";

    // 1. Открываем файл для чтения и записи
    int fd = open(filename, O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // 2. Получаем размер файла
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("fstat");
        close(fd);
        return 1;
    }
    size_t file_size = sb.st_size;

    // 3. Отображаем файл в память
    //    PROT_READ | PROT_WRITE — права доступа к отображё

# Lock-Free Queue Library

Библиотека для обмена данными между потоками с использованием очередей без блокировок (lock-free). Обеспечивает высокую производительность и масштабируемость в многопоточных приложениях за счёт атомарных операций вместо мьютексов.

## Назначение

Библиотека предоставляет потокобезопасные очереди, которые позволяют:
- Передавать данные между потоками без блокировок
- Избегать взаимных блокировок (deadlocks)
- Достигать высокой пропускной способности при интенсивном многопоточном доступе
- Гарантировать корректность операций в условиях конкурентного доступа

Подходит для систем реального времени, высоконагруженных сервисов, игровых движков и других приложений, где критична низкая задержка и высокая производительность.

## Установка

### Через CMake

```cmake
find_package(LockFreeQueue REQUIRED)
target_link_libraries(your_target PRIVATE LockFreeQueue::LockFreeQueue)
```

### Через vcpkg

```bash
vcpkg install lock-free-queue
```

### Через Conan

```bash
conan install lock-free-queue/1.0.0@user/channel
```

### Ручная сборка

```bash
git clone https://github.com/example/lock-free-queue.git
cd lock-free-queue
mkdir build && cd build
cmake .. -DCMAKE_BUILD_TYPE=Release
cmake --build .
sudo cmake --install .
```

## Пример использования

### Базовый пример: передача целых чисел между потоками

```cpp
#include <lock_free_queue/queue.hpp>
#include <thread>
#include <iostream>
#include <atomic>

int main() {
    // Создаём очередь на 1024 элемента
    lock_free::Queue<int> queue(1024);

    std::atomic<bool> producer_done{false};
    std::atomic<int> sum{0};

    // Поток-производитель
    std::thread producer([&]() {
        for (int i = 1; i <= 1000; ++i) {
            while (!queue.push(i)) {
                // Очередь полна — ждём освобождения места
                std::this_thread::yield();
            }
        }
        producer_done.store(true);
    });

    // Поток-потребитель
    std::thread consumer([&]() {
        int value;
        while (!producer_done.load() || !queue.empty()) {
            if (queue.pop(value)) {
                sum.fetch_add(value);
            } else {
                std::this_thread::yield();
            }
        }
    });

    producer.join();
    consumer.join();

    std::cout << "Сумма: " << sum.load() << std::endl;
    // Вывод: Сумма: 500500

    return 0;
}
```

